"""Aggregate all seeds and failures; preserve reconstruction/generation boundaries."""
import json
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
root=Path(__file__).resolve().parents[1];out=root/'results/round2'
from rigel3d.data import load_assets
gt_counts={r['record']['asset_name']:len(r['joints']) for r in load_assets(root)['test']}
def ms(values):return dict(mean=float(np.mean(values)),std=float(np.std(values,ddof=1)))
groups=[]
for suite,label in [('round2_geometry','Geometry proxy'),('round2_dino','Real DINO'),('round2_vae','Sparse VAE')]:
    seeds=[]
    for seed in [0,1,2]:
        p=root/f'results/{suite}/rig/seed{seed}/evaluation_metrics_v2.json';r=json.loads(p.read_text());rows=r['splits']['test'];eligible=[a for a in rows if a['skeleton_eligible']]
        seeds.append(dict(seed=seed,skin_l1=float(np.mean([a['skin']['l1_element'] for a in rows])),j2j=float(np.mean([a['skeleton']['j2j'] for a in eligible])),j2b=float(np.mean([a['skeleton']['j2b'] for a in eligible])),b2b=float(np.mean([a['skeleton']['b2b'] for a in eligible])),cap_hits=sum(a['capped'] for a in eligible),count_mean=float(np.mean([a['generated_joint_count'] for a in eligible])),count_mae=float(np.mean([abs(a['generated_joint_count']-gt_counts[a['asset_name']]) for a in eligible])),teacher_j2j=float(np.mean([a['teacher_forced_geometry_diagnostic']['j2j'] for a in eligible])),coordinate_accuracy=float(np.mean([a['teacher_forced']['coordinate_accuracy'] for a in eligible])),eos_recall=float(np.mean([a['teacher_forced']['eos_at_true_end'] for a in eligible])),quantization_j2j=float(np.mean([a['quantized_gt_oracle']['j2j'] for a in eligible]))))
    groups.append(dict(suite=suite,label=label,runs=seeds,metrics={k:ms([r[k] for r in seeds]) for k in seeds[0] if k not in ['seed','cap_hits']},cap_hits=sum(r['cap_hits'] for r in seeds),evaluations=30))
vae={m:dict(test_mse=ms([json.load(open(out/f'vae4000/seed{s}/{m}/evaluation.json'))['metrics']['test']['mse'] for s in [0,1,2]])) for m in ['surface','rig']}
generation=[]
for seed in [0,1,2]:
    r=json.load(open(out/f'generation/seed{seed}/evaluation.json'));rows=r['assets'];valid=[a['generation'] for a in rows if a['generation'].get('mesh_chamfer') is not None];gen=[a['generation'] for a in rows]
    generation.append(dict(seed=seed,test_assets=len(rows),mesh_valid=len(valid),failures=sum(a.get('failure') is not None for a in gen),cap_hits=sum(a.get('capped',False) for a in gen),mesh_chamfer_nonempty=float(np.mean([a['mesh_chamfer'] for a in valid])) if valid else None,mesh_chamfer_all_with_empty_penalty=float(np.mean([a.get('mesh_chamfer') if a.get('mesh_chamfer') is not None else np.sqrt(3) for a in gen])),j2j_all_with_empty_penalty=float(np.mean([a['skeleton']['j2j'] if 'skeleton' in a else np.sqrt(3) for a in gen])),gt_latent_reconstruction_mesh_valid=sum(a['gt_latent_reconstruction']['mesh_chamfer'] is not None for a in rows),gt_latent_reconstruction_chamfer=float(np.mean([a['gt_latent_reconstruction']['mesh_chamfer'] if a['gt_latent_reconstruction']['mesh_chamfer'] is not None else np.sqrt(3) for a in rows])),gt_latent_reconstruction_sdf_mae=float(np.mean([a['gt_latent_reconstruction']['sdf_mae'] for a in rows]))))
sensitivity=[]
for cfg,suite in [(1,'generation_cfg1'),(3,'generation_cfg3'),(5,'generation')]:
    cases=[a['generation'] for seed in [0,1,2] for a in json.load(open(out/f'{suite}/seed{seed}/evaluation.json'))['assets']]
    sensitivity.append(dict(cfg=cfg,nonempty_meshes=sum(a.get('mesh_chamfer') is not None for a in cases),evaluations=len(cases),cap_hits=sum(a.get('capped',False) for a in cases),j2j_mean=float(np.mean([a['skeleton']['j2j'] for a in cases if 'skeleton' in a]))))
shift=json.load(open(out/'generation_shift_audit.json'))
shift_summary={m:{k:float(np.mean([r[m][k] for r in shift['assets'] if m in r])) for k in ['normalized_latent_rms','coarse_occupancy_iou']} for m in ['surface','rig']}
summary=dict(scope='Fixed source cohort:25 train/6 val/10 test,24/6/10 eligible skeletons; three seeds all reported. Decoder reconstruction uses GT rig geometry/weights; strict generation only uses one image plus noise.',reconstruction=groups,sparse_vae=vae,generation=dict(runs=generation,metrics={k:ms([r[k] for r in generation]) for k in ['mesh_chamfer_all_with_empty_penalty','j2j_all_with_empty_penalty','gt_latent_reconstruction_chamfer','gt_latent_reconstruction_sdf_mae']},failure_count=sum(r['failures'] for r in generation),mesh_valid=sum(r['mesh_valid'] for r in generation),evaluations=30),cfg_sensitivity=sensitivity,generation_shift=shift_summary,uncertainty='Mean and sample SD over three training seeds. Not benchmark confidence intervals.',claim='Independent small pipeline verification, not original architecture/scale, paper baselines or numerical reproduction. All original paper tables remain unmatched.')
(out/'summary.json').write_text(json.dumps(summary,indent=2)+'\n')
plt.rcParams.update({'font.size':10,'axes.spines.top':False,'axes.spines.right':False});fig,axs=plt.subplots(2,2,figsize=(10,6),layout='constrained');colors=['#0072B2','#009E73','#D55E00']
for i,g in enumerate(groups):
    for ax,key in [(axs[0,0],'skin_l1'),(axs[0,1],'j2j')]:
        ax.scatter(i+np.linspace(-.08,.08,3),[r[key]*100 for r in g['runs']],color=colors[i]);m=g['metrics'][key];ax.errorbar(i,m['mean']*100,yerr=m['std']*100,c=colors[i],capsize=4)
    axs[1,0].bar(i,100*g['cap_hits']/30,color=colors[i])
for ax in [axs[0,0],axs[0,1],axs[1,0]]:ax.set_xticks(range(3),[g['label'] for g in groups],rotation=10)
axs[0,0].set_ylabel('GT-bone skin L1 element ×100');axs[0,1].set_ylabel('Free skeleton, GT context J2J ×100');axs[1,0].set_ylabel('96-joint cap hits (%)');axs[1,0].set_ylim(0,105)
for i,key in enumerate(['gt_latent_reconstruction_chamfer','mesh_chamfer_all_with_empty_penalty']):
    vals=[r[key]*100 for r in generation];axs[1,1].scatter(np.full(3,i)+np.linspace(-.08,.08,3),vals,c=colors[i]);axs[1,1].errorbar(i,np.mean(vals),yerr=np.std(vals,ddof=1),c=colors[i],capsize=4)
axs[1,1].set_xticks([0,1],['GT-latent reconstruction','Image-only generation'],rotation=10);axs[1,1].set_ylabel('Mesh Chamfer ×100 (empty penalty)');fig.savefig(out/'comparison.png',dpi=170);plt.close(fig)
lines=['# Round 2: real DINO, Sparse VAE and strict image-only pilot','',summary['scope'],'',summary['claim'],'','Mean ± sample SD across seeds. All distances below ×100. No direct comparison with original paper tables.','','| GT-context reconstruction | Skin L1 element | J2J | J2B | B2B | Cap hits /30 |','|---|---:|---:|---:|---:|---:|']
for g in groups:
    v=[f"{g['metrics'][k]['mean']*100:.3f} ± {g['metrics'][k]['std']*100:.3f}" for k in ['skin_l1','j2j','j2b','b2b']];lines.append('| '+g['label']+' | '+' | '.join(v)+f" | {g['cap_hits']}/30 |")
lines+=['','## Sparse VAE component','',f"Normalized real-DINO feature test MSE: surface {vae['surface']['test_mse']['mean']:.4f} ± {vae['surface']['test_mse']['std']:.4f}; rig {vae['rig']['test_mse']['mean']:.4f} ± {vae['rig']['test_mse']['std']:.4f}. Ground-truth active coordinates are retained. This is feature reconstruction, not learned occupancy or mesh generation.",'','## Strict image-only generation','',f"Nonempty extracted meshes: {summary['generation']['mesh_valid']}/30; reported failure flags: {summary['generation']['failure_count']}/30. Every failure remains in per-asset reports.",'','| Path | Mesh Chamfer ×100 | J2J ×100 |','|---|---:|---:|']
for label,mkey,jkey in [('GT-latent reconstruction','gt_latent_reconstruction_chamfer',None),('Image-only generation','mesh_chamfer_all_with_empty_penalty','j2j_all_with_empty_penalty')]:
    m=summary['generation']['metrics'][mkey];j=summary['generation']['metrics'][jkey] if jkey else None;lines.append(f"| {label} | {m['mean']*100:.3f} ± {m['std']*100:.3f} | "+(f"{j['mean']*100:.3f} ± {j['std']*100:.3f}" if j else 'not this diagnostic')+' |')
lines+=['','Empty mesh/skeleton cases receive sqrt(3), the unit-box diameter, in the all-case diagnostic aggregate; nonempty-only distances and denominators are also retained. Chamfer uses 2048 area-weighted sampled mesh points, 8192 target points, unsquared symmetric mean/2. Skinning on generated topology is checked for normalization only: no same-index GT-skin accuracy claim.','','## Guidance and distribution diagnostics','', 'The CFG5 setting remains the main result. The following are matched-noise test sensitivity audits, not a test-selected replacement.','','| CFG | Nonempty meshes /30 | 96-joint caps /30 | J2J ×100 |','|---|---:|---:|---:|']
for r in sensitivity:lines.append(f"| {r['cfg']} | {r['nonempty_meshes']}/30 | {r['cap_hits']}/30 | {r['j2j_mean']*100:.3f} |")
lines += ['',f"CFG5 mean coarse occupancy IoU: surface {shift_summary['surface']['coarse_occupancy_iou']:.4f}, rig {shift_summary['rig']['coarse_occupancy_iou']:.4f}. Generated normalized latent RMS: surface {shift_summary['surface']['normalized_latent_rms']:.3f}, rig {shift_summary['rig']['normalized_latent_rms']:.3f}, versus train RMS=1 by normalization. These show occupancy error and distribution shift; guidance alone does not resolve failures.",'','## Known gaps','', '- Random initialization; no pretrained TRELLIS surface encoder or mesh decoder, unlike the original method.','- DINOv2-S 384 channels, four neutral 224px views; original TRELLIS configuration uses DINOv2-L/reg 1024 channels and 512px images.','- Seven-tap axial sparse VAE, width32/8 latent channels; separately trained feature loss+KL, not original joint autoencoder losses or pretrained sparse transformer.','- Direct 16³ occupancy MLP flows lack original occupancy VAEs, sparse flow transformers and cross-branch coupling.','- Independent cross-attention field decoder predicts a 17³ vertex grid; fixed upstream FlexiCubes uses default blend weights, no learned vertex deformations.','- Oriented-nearest-triangle SDF is weak supervision on open/inconsistently oriented meshes; original differentiable rendering losses absent.','- Decoder models are small width64/two-layer, frozen VAE means and GT-rig reconstruction context. The 25/6/10 aligned-asset cohort is not the complete benchmark.','- Semantic joint labels, textures, retargeting and original paper baselines/ablation tables remain unimplemented/unmatched.','','See docs/round2_experiments.md for source, exclusions, commands and inference boundaries.']
(out/'REPORT.md').write_text('\n'.join(lines)+'\n');print(json.dumps(summary['generation']))
